/**
 * Generates TypeScript files. Print lines of text and identifiers to a
 * {@link File}, and it works out their imports when it renders.
 *
 * ```ts
 * import { file, module } from "@cloudflare/forge/ts";
 *
 * const models = module("pets/models.ts");
 * const f = file("pets/client.ts");
 * f.doc("A client of pets.");
 * f`export interface ${f.ident("Client")} {`;
 * f.indent(() => {
 *   f`get(): Promise<${models.ident("Pet").ty()}>;`;
 * });
 * f`}`;
 * ```
 *
 * renders as:
 *
 * ```ts
 * // Code generated by forge. DO NOT EDIT.
 * /* eslint-disable *\/
 *
 * import type { Pet } from "./models.js";
 *
 * /**
 *  * A client of pets.
 *  *\/
 * export interface Client {
 *   get(): Promise<Pet>;
 * }
 * ```
 *
 * A `File` is a plugin's file as it is: return it from `generate` or
 * `generateGroup`. One with nothing printed renders as nothing, so forge
 * doesn't write it.
 *
 * This is forge's Rust `forge::ts`, and renders the same text, with tagged
 * templates in place of its macros: `` f`…` ``, calling the file, for `p!`, `` frag`…` ``
 * for `frag!`.
 *
 * @module
 */
import type { Group, Model } from './index.js';
/**
 * The first lines of every file. They mark it as generated and turn off
 * ESLint.
 */
export declare const PREAMBLE = "// Code generated by forge. DO NOT EDIT.\n/* eslint-disable */\n\n";
/**
 * Something a line can print. Strings print as they are, and numbers,
 * booleans and bigints as `String` writes them. An {@link Ident} prints
 * under the name the file uses for it, and is imported if it comes from
 * another module. A {@link Model} prints as its identifier,
 * {@link ident.model}. An array prints each of its parts in turn, with
 * nothing between them: use {@link join} for a list with separators.
 *
 * Anything else, such as `undefined` or an object of a plugin's own, is an
 * error, rather than printing as `undefined` or `[object Object]`: use
 * `String(x)` for a value of your own.
 */
export type Part = string | number | boolean | bigint | Ident | Model | readonly Part[];
/** The key that only modules have, which {@link isModule} looks for. */
declare const MODULE: unique symbol;
/** The key that only identifiers have, which {@link isIdent} looks for. */
declare const IDENT: unique symbol;
/**
 * A TypeScript module that files can import: a generated file or a
 * package. Make one with {@link module}.
 *
 * A module ending in `.ts` is a generated file, named by its path from the
 * output directory, such as `pets/models.ts`. Other generated files import
 * it by a relative specifier ending in `.js`, such as `./models.js`, which
 * is how TypeScript resolves it. Any other module is a package, such as
 * `zod` or `node:fs`, and files import it by that specifier unchanged.
 */
export interface Module {
    readonly [MODULE]: true;
    /** The path, for a generated file, or the specifier, for a package. */
    readonly path: string;
    /** Whether the module is a generated file. */
    readonly generated: boolean;
    /** Returns the identifier called `name` declared in this module. */
    ident(name: string): Ident;
    /**
     * Returns the module `name` inside the directory `this`:
     * `module("pets").sub("models.ts")` is `pets/models.ts`.
     */
    sub(name: string): Module;
    /** Whether `other` is the same module. */
    equals(other: Module): boolean;
    /** The path. */
    toString(): string;
}
/**
 * A TypeScript identifier: a name and the module that declares it. A file
 * that prints an identifier from another module imports it. Make one with
 * {@link ident}, or a module's `ident`.
 *
 * It is immutable: `ty` and `as` return new identifiers.
 */
export interface Ident {
    readonly [IDENT]: true;
    /** The name, such as `Pet`, or a dotted one such as `Temporal.Instant`. */
    readonly name: string;
    readonly module: Module;
    /**
     * Whether the identifier is only a type. Files import types with
     * `import type`, or with `type` in front of the name when the same
     * declaration also imports values.
     */
    readonly typeOnly: boolean;
    /**
     * The name a file imports the identifier under, as in
     * `import { Name as Alias }`, and uses for it. If the alias is already
     * taken in the file, it still gets `$` appended. A file ignores the alias
     * of its own identifiers, since it doesn't import them.
     */
    readonly alias: string | undefined;
    /** Returns the identifier marked as only a type. */
    ty(): Ident;
    /** Returns the identifier imported under `alias`. */
    as(alias: string): Ident;
    /** The name unchanged, such as `Temporal.Instant`; a file may print an alias instead. */
    toString(): string;
}
/**
 * A TypeScript file: its module and the lines printed to it. Make one with
 * {@link file}.
 *
 * Print a line by calling the file, as in `` f`let pet: ${pet};` ``, and a
 * comment with `doc`. The file renders them only once it knows every
 * import, so it can give conflicting names aliases.
 */
export interface File {
    /**
     * Prints a line: the file's indentation, the template's parts, then a
     * line break.
     *
     * ```ts
     * f`let pet: ${pet};`;
     * ```
     *
     * If the parts print nothing but empty text, the line is blank, with no
     * indentation. Only the start of the line is indented, so the template
     * shouldn't contain line breaks.
     */
    (strings: TemplateStringsArray, ...parts: Part[]): void;
    /**
     * Prints a line of `parts`, in turn, for parts made at run time:
     *
     * ```ts
     * f("let pet: ", pet, ";");
     * f(); // a blank line
     * ```
     */
    (...parts: Part[]): void;
    /** The module of the file. */
    readonly module: Module;
    /** The path of the file, relative to the output directory. */
    readonly path: string;
    /**
     * The rendered file: the preamble, the imports, then the lines printed to
     * the file, or nothing if nothing was printed.
     *
     * The imports list packages first, then generated files, each sorted by
     * specifier, with one declaration per module. A module whose names are
     * all only types is imported with `import type`, and a name used both as
     * a type and as a value is imported as a value. If an imported name
     * clashes with one the file declares or an earlier import, it gets an
     * alias with `$` appended.
     */
    readonly content: string;
    /** Returns an identifier declared in this file. */
    ident(name: string): Ident;
    /**
     * Calls `f` with the file indented one more level, so the lines and
     * comments it prints get two more spaces.
     */
    indent(f: (file: File) => void): void;
    /**
     * Prints `text` as a JSDoc comment at the file's indentation. It trims
     * the text, prints each line after ` * `, and wraps words to fit in 80
     * columns, giving a word longer than a line a line of its own. It escapes
     * `*\/` so the text can't end the comment early, and prints nothing for
     * empty text.
     */
    doc(text: string): void;
    /** Returns the rendered file, as `content` describes it. */
    render(): string;
}
/** Returns the module at `path`: a generated file if it ends in `.ts`, and a package otherwise. */
export declare const module: {
    (path: string): Module;
    /** The output directory. Its `sub` modules are the top-level files. */
    readonly ROOT: Module;
    /**
     * Returns the directory that holds `group`'s files: the group's path,
     * with each name in camelCase and prefixed with `_` if it starts with a
     * digit. A group `list_all` inside `pet-store` gets `petStore/listAll`.
     * Top-level files go in `module.ROOT` instead.
     */
    group(group: Pick<Group, 'path'>): Module;
};
/** Returns the identifier `name`, declared in `module`. */
export declare const ident: {
    (name: string, module: Module, options?: {
        readonly typeOnly?: boolean;
        readonly alias?: string | undefined;
    }): Ident;
    /**
     * Returns the identifier of `model`: its name in PascalCase, prefixed
     * with `_` if it starts with a digit, declared in the `models.ts` of its
     * group's directory (`module.group`), or of the root for a top-level
     * model. Call `ty` on it to import it with `import type`.
     *
     * A plugin that names models differently makes its own identifier, and
     * prints that one everywhere it refers to the model.
     */
    model(model: Pick<Model, 'name' | 'group'>): Ident;
};
/**
 * Returns the parts of a template, in order, to print as part of a line
 * later:
 *
 * ```ts
 * const list = frag`Promise<${pet}[]>`;
 * f`list(): ${list};`;
 * ```
 */
export declare function frag(strings: TemplateStringsArray, ...parts: Part[]): Part[];
/**
 * Returns `parts` with `sep` between each two of them, leaving out the
 * parts that print nothing:
 *
 * ```ts
 * f`const all = [${join(", ", ["a", "", "c"])}];`; // const all = [a, c];
 * ```
 */
export declare function join(sep: string, parts: Iterable<Part>): Part[];
/**
 * Returns an empty file at `module`, or at the module with that path.
 *
 * ```ts
 * const f = file("pets/client.ts");
 * f`export interface ${f.ident("Client")} {}`;
 * ```
 */
export declare function file(at: Module | string): File;
export {};
